items.referenceSolution:
import java.util.Scanner;

class BadFishCountException extends Exception {
    BadFishCountException(String msg) {
        super(msg);
    }
}

public class Main {
    static int take(int n, int have) throws BadFishCountException {
        if (n < 0) {
            throw new BadFishCountException("数量不能是负的");
        }
        if (n > have) {
            throw new BadFishCountException("变量中只有 " + have + " 条");
        }
        return n;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int have = 4;
        int total = sc.nextInt();
        int bad = 0;
        int sum = 0;
        for (int i = 0; i < total; i++) {
            int n = sc.nextInt();
            try {
                sum += take(n, have);
            } catch (BadFishCountException e) {
                bad++;
                System.out.println("第 " + bad + " 笔出事：" + e.getMessage());
            }
        }
        System.out.println("出了 " + bad + " 次事，收下 " + sum + " 条");
    }
}

